const input = $input.first().json;
const body = input.body ?? input;
const record = body.record ?? body;

if (!record || !record.email) {
  throw new Error('Kein record.email im Webhook-Payload. Keys: ' + Object.keys(body).join(', '));
}

const yesNo = (v) => (v ? 'Ja' : 'Nein');
const consents = Array.isArray(record.consents) ? record.consents : [];
const consentLines = consents.length
  ? consents.map((c) => `${c.purpose}: ${c.granted ? 'erteilt' : 'nicht erteilt'} (${c.text_version || ''})`)
  : ['Datenschutz: ' + yesNo(record.privacy_ack), 'Marketing: ' + yesNo(record.marketing_consent)];
const calUrl = record.cal_url || 'https://cal.com/ritzaisolutions/immo-ai-roadmap';
const name = record.name || 'Sie';

return [{
  json: {
    kevin: {
      to: body.to || 'kevin@ritz-ai.solutions',
      subject: body.subject || ('Neuer Funnel-Lead: ' + name),
      text: body.text || [
        'Neuer Qualifizierungs-Lead auf ritz-ai.solutions/ai-roadmap.html',
        '',
        'Name: ' + name,
        'E-Mail: ' + record.email,
        'Telefon: ' + (record.phone || '—'),
        'Vorgangstyp: ' + (record.vorgangstyp || '—'),
        'Volumen/Woche: ' + (record.volumen_woche ?? '—'),
        'CRM: ' + (record.crm || '—'),
        'Quelle: ' + (record.source || '—'),
        '',
        'Consent:',
        ...consentLines,
        'Version: ' + (record.consent_version || '—'),
        'Lead-ID: ' + (record.id || '—')
      ].join('\n')
    },
    userConfirm: {
      to: record.email,
      subject: 'Ihre KI-Roadmap bei RAIS',
      text: [
        'Guten Tag ' + name + ',',
        '',
        'wir haben Ihre Angaben erhalten. Als Nächstes wählen Sie bitte Ihren Termin:',
        calUrl,
        '',
        '60 Minuten, kostenlos. Wenn es nicht passt, sagen wir das.',
        '',
        'Kevin Ritz',
        'RAIS · Ritz AI Solutions'
      ].join('\n')
    },
    userReminder: {
      to: record.email,
      subject: 'Erinnerung: Termin für Ihre KI-Roadmap',
      text: [
        'Guten Tag ' + name + ',',
        '',
        'kurze Erinnerung: Ihr Termin für die KI-Roadmap ist noch offen.',
        'Hier können Sie ihn in 60 Minuten buchen:',
        calUrl,
        '',
        'Wenn Sie schon gebucht haben, können Sie diese Mail ignorieren.',
        '',
        'Kevin Ritz',
        'RAIS · Ritz AI Solutions'
      ].join('\n')
    },
    record
  }
}];
